e" value="1"><button class="text-button <?= $action==='delete'?'danger':'' ?>"><?= $label ?></button></form><?php endforeach ?></div></td></tr><?php endforeach ?></tbody></table><?php if(!$shown): ?><p>No offers match these filters.</p><?php endif ?></div>
